import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// Define the schema for user controls


export type SleekMLogoProps = Record<string, any>;

const SleekMLogo: React.FC<SleekMLogoProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  logoScale = 1,
  noiseOpacity = 0.15,
  strokeThickness = 45,
}) => {
  // Load fonts (even if not strictly used for text, good practice to keep the hook)
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Calculations & Parsing ---
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Center the logo
  const size = Math.min(width, height) * 0.6 * logoScale;
  const xOffset = (width - size) / 2;
  const yOffset = (height - size) / 2;

  // The "M" Path Logic
  // A standard M path: Start Bottom-Left -> Top-Left -> Middle-V -> Top-Right -> Bottom-Right
  // We use a relative 200x200 coordinate system for the path string
  const mPath = "M 45 170 L 45 30 L 100 110 L 155 30 L 155 170";
  
  // --- Animations ---

  // 1. Entrance Spring (Scale & Opacity)
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 200, stiffness: 100, mass: 3 },
    durationInFrames: 60,
  });

  // 2. Stroke Evolution (Drawing the gradient outline)
  // Starts a bit later for a staggered effect
  const strokeEvolution = evolvePath(
    spring({
      frame: frame - 10,
      fps,
      config: { damping: 200, stiffness: 50 },
      delay: 0,
    }),
    mPath
  );

  // 3. Fill Opacity (The white part fading in)
  const fillOpacity = interpolate(
    frame,
    [20, 50],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 4. Blur Transition (Sleek Apple style: blur -> sharp)
  const blurAmount = interpolate(
    frame,
    [0, 45],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 5. Dynamic Noise
  // We shift the noise seed slightly every few frames to simulate film grain activity
  const noiseSeed = Math.floor(frame / 2);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* 1. SVG Filters Definition */}
      <svg style={{ position: "absolute", width: 0, height: 0 }}>
        <defs>
          {/* Grain Filter */}
          <filter id="grain">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.8"
              numOctaves="3"
              stitchTiles="stitch"
              seed={noiseSeed} 
            />
            <feColorMatrix type="saturate" values="0" />
            <feComponentTransfer>
               <feFuncA type="linear" slope={noiseOpacity} />
            </feComponentTransfer>
          </filter>

          {/* Vertical Gradient: Red -> Yellow -> Blue */}
          <linearGradient id="logoGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#FF3B30" /> {/* Apple Red */}
            <stop offset="50%" stopColor="#FFCC00" /> {/* Apple Yellowish */}
            <stop offset="100%" stopColor="#007AFF" /> {/* Apple Blue */}
          </linearGradient>

          {/* Drop Shadow for depth */}
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
             <feGaussianBlur in="SourceAlpha" stdDeviation="15" result="blur" />
             <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>
      </svg>

      {/* 2. Main Logo Container */}
      <div
        style={{
          position: "absolute",
          left: xOffset,
          top: yOffset,
          width: size,
          height: size,
          transform: `scale(${0.9 + (entranceSpring * 0.1)})`, // Subtle scale up 0.9 -> 1.0
          opacity: Math.min(1, frame / 10), // Quick fade in of container
          filter: `blur(${blurAmount}px)`,
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 200 200"
          width="100%"
          height="100%"
          style={{ overflow: "visible" }}
        >
          {/* Layer 1: The Gradient Stroke (Backing) */}
          <path
            d={mPath}
            fill="none"
            stroke="url(#logoGradient)"
            strokeWidth={strokeThickness + 10} // Slightly thicker than the white fill
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={strokeEvolution.strokeDasharray}
            strokeDashoffset={strokeEvolution.strokeDashoffset}
            style={{
              opacity: 1, 
              filter: "url(#glow)",
            }}
          />

          {/* Layer 2: The White Fill (Inner) */}
          <path
            d={mPath}
            fill="none"
            stroke="#F5F5F7" // Off-white/Apple white
            strokeWidth={strokeThickness}
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              opacity: fillOpacity,
            }}
          />
        </svg>
      </div>

      {/* 3. Noise Overlay */}
      {/* We use a rect filled with the noise filter on top of everything */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
          mixBlendMode: "overlay", // Blends grain nicely with dark bg
        }}
      >
        <svg width="100%" height="100%">
          <rect width="100%" height="100%" filter="url(#grain)" opacity={1} />
        </svg>
      </div>

    </AbsoluteFill>
  );
};

export default SleekMLogo;